package com.example.leetcodetrainer.adaptive.service;
import com.example.leetcodetrainer.adaptive.domain.*; import com.example.leetcodetrainer.attempt.domain.StageType; import java.util.*; import org.springframework.stereotype.Service;
@Service public class ReasoningProfileService { public List<ProfileStageDefinition> stagesFor(ReasoningProfileType p){ if(p==ReasoningProfileType.RECURSIVE_DIVIDE_AND_COMBINE)return List.of(new ProfileStageDefinition(p,StageType.PROBLEM_RELATION,StageApplicability.REQUIRED,"再帰関数の契約","この関数は何を返しますか？",List.of(),1),new ProfileStageDefinition(p,StageType.RESOLUTION_EVENT,StageApplicability.REQUIRED,"最小入力と答え","これ以上分解できない最小入力と答えは何ですか？",List.of(),2),new ProfileStageDefinition(p,StageType.UPDATED_REGION,StageApplicability.REQUIRED,"同じ形の部分問題","どの小さい同型問題に分けますか？",List.of(),3),new ProfileStageDefinition(p,StageType.UNRESOLVED_STATE,StageApplicability.REQUIRED,"子から受け取る情報","各部分問題は何を返しますか？",List.of(),4),new ProfileStageDefinition(p,StageType.REQUIRED_OPERATIONS,StageApplicability.REQUIRED,"子の答えの合成","子の答えを現在のnodeでどう組み合わせますか？",List.of(),5),new ProfileStageDefinition(p,StageType.DATA_STRUCTURE_SELECTION,StageApplicability.NOT_APPLICABLE,"データ構造選択","",List.of(),6),new ProfileStageDefinition(p,StageType.REPEATED_WORK,StageApplicability.NOT_APPLICABLE,"重複処理","",List.of(),7)); return StageType.ordered().stream().map(s->new ProfileStageDefinition(p,s,StageApplicability.REQUIRED,s.getDisplayName(),s.getPrimaryQuestion(),s.getHelperQuestions(),s.getOrder())).toList(); } public ReasoningProfileType profileForSlug(String slug){return "maximum-depth-of-binary-tree".equals(slug)?ReasoningProfileType.RECURSIVE_DIVIDE_AND_COMBINE:ReasoningProfileType.LOOKUP_STATE;} }
